-- +goose Up
-- Backup snapshot of all companies as of 2026-04-27.
-- Safe to replay on any environment: ON CONFLICT upserts every row to match this snapshot.
-- Does NOT touch created_at or last_scan_at — those are left as-is on existing rows.

ON CONFLICT (id) DO UPDATE SET
    name                           = EXCLUDED.name,
    url                            = EXCLUDED.url,
    adapter_type                   = EXCLUDED.adapter_type,
    active                         = EXCLUDED.active,
    last_scan_status               = EXCLUDED.last_scan_status,
    scan_interval_minutes_override = EXCLUDED.scan_interval_minutes_override;

